const PREFIX = {users:'USR',activity_logs:'LOG',academic_years:'AY',majors:'MJR',classes:'CLS',students:'STU',teachers:'TCH',industries:'IND',industry_mentors:'IMT',periods:'PRD',teacher_industry_assignments:'TIA',placements:'PLC',qr_sessions:'QRS',attendance:'ATT',attendance_logs:'ATL',journals:'JRN',monitoring:'MON',assessments:'ASM',certificates:'CRT',documents:'DOC',notifications:'NTF',notification_logs:'NLG',media_files:'MED',backup_logs:'BKP',dashboard_cache:'DCH'};

