function doGet(e){try{const p=e&&e.parameter?e.parameter:{}; const out=handleRequest_(String(p.action||'ping'),p,'GET'); if(p.callback)return ContentService.createTextOutput(p.callback+'('+out.getContent()+')').setMimeType(ContentService.MimeType.JAVASCRIPT); return out;}catch(err){return jsonResponse_(false,err.message,{stack:APP_CONFIG.APP_MODE==='development'?err.stack:''});}}
function doPost(e){try{const d=parsePostData_(e); if(!d.action)return jsonResponse_(false,'Action wajib diisi.',null); return handleRequest_(String(d.action),d,'POST');}catch(err){return jsonResponse_(false,err.message,{stack:APP_CONFIG.APP_MODE==='development'?err.stack:''});}}
function parsePostData_(e){if(!e||!e.postData||!e.postData.contents)return{}; try{return JSON.parse(e.postData.contents);}catch(err){const o={}; String(e.postData.contents).split('&').forEach(s=>{const p=s.split('='); if(p[0])o[decodeURIComponent(p[0])]=decodeURIComponent(p[1]||'');}); return o;}}
function jsonResponse_(success,message,data){return ContentService.createTextOutput(JSON.stringify({success:success===true,message:message||'',data:data===undefined?null:data,timestamp:now_()})).setMimeType(ContentService.MimeType.JSON);}

