    listClasses:()=>listGeneric_(data,'classes'), createClass:()=>createGeneric_(data,CRUD.classes), updateClass:()=>updateGeneric_(data,CRUD.classes), deleteClass:()=>deleteGeneric_(data,'classes'),
    listStudents:()=>handleListStudents_(data), createStudent:()=>handleCreateStudent_(data), updateStudent:()=>handleUpdateStudent_(data), deleteStudent:()=>deleteGeneric_(data,'students'),
    listTeachers:()=>listGeneric_(data,'teachers'), createTeacher:()=>handleCreateTeacher_(data), updateTeacher:()=>updateGeneric_(data,CRUD.teachers), deleteTeacher:()=>deleteGeneric_(data,'teachers'),
