function successMessage_(a){return 'Action '+a+' berhasil diproses.';}

function setupDatabase(){const ss=getOrCreateSpreadsheet_(); Object.keys(DB_SHEETS).forEach(n=>{let sh=ss.getSheetByName(n)||ss.insertSheet(n); setupSheetHeaders_(sh,DB_SHEETS[n]);}); setupDefaultSettings_(); setupDefaultUsers_(); return{spreadsheet_id:ss.getId(),spreadsheet_url:ss.getUrl(),sheets:Object.keys(DB_SHEETS),setup_completed_at:now_()};}
function getOrCreateSpreadsheet_(){const p=PropertiesService.getScriptProperties(); const id=p.getProperty('SPREADSHEET_ID'); if(id){try{return SpreadsheetApp.openById(id)}catch(e){}} const ss=SpreadsheetApp.create(APP_CONFIG.APP_NAME+' Database'); p.setProperty('SPREADSHEET_ID',ss.getId()); p.setProperty('APP_SECRET',Utilities.getUuid()); return ss;}
function setupSheetHeaders_(sh,headers){const lc=sh.getLastColumn(); if(!lc){sh.getRange(1,1,1,headers.length).setValues([headers]); sh.setFrozenRows(1); return;} const old=sh.getRange(1,1,1,Math.max(lc,headers.length)).getValues()[0].map(x=>String(x||'').trim()).filter(Boolean); headers.forEach(h=>{if(old.indexOf(h)<0)old.push(h)}); sh.getRange(1,1,1,old.length).setValues([old]); sh.setFrozenRows(1);}
function setupDefaultSettings_(){[['school_name',APP_CONFIG.SCHOOL_NAME,'Nama sekolah'],['school_address','Randudongkal, Pemalang','Alamat sekolah'],['items_per_page','10','Data per halaman'],['active_period_id','','Periode aktif'],['qr_expire_minutes','30','Masa aktif QR'],['wa_enabled','false','Status WA'],['wa_provider','WAPLUS','Provider WA'],['wa_api_url','','URL WA'],['wa_api_key','','API Key WA'],['wa_sender_number','','Nomor WA'],['attendance_notify_parent','true','Notif orang tua'],['attendance_notify_homeroom','true','Notif wali kelas'],['attendance_notify_humas','true','Notif humas'],['attendance_notify_kurikulum','true','Notif kurikulum'],['waka_humas_name','Waka Humas','Nama humas'],['waka_humas_phone','','WA humas'],['waka_kurikulum_name','Waka Kurikulum','Nama kurikulum'],['waka_kurikulum_phone','','WA kurikulum'],['drive_upload_root_folder_id','','Folder utama upload file di Google Drive'],['upload_public_access','true','File upload dapat diakses melalui link'],['upload_store_metadata_only','true','File disimpan di Drive, Spreadsheet hanya metadata'],['app_logo_url','','URL logo aplikasi'],['school_logo_url','','URL logo sekolah'],['app_icon_url','','URL icon aplikasi/PWA'],['favicon_url','','URL favicon aplikasi'],['favicon_mime_type','','MIME type favicon'],['favicon_file_extension','','Ekstensi file favicon'],['pwa_enabled','true','Status PWA'],['app_theme_color','#0b6edc','Warna tema aplikasi'],['playstore_ready','true','Status kesiapan Play Store']].forEach(r=>{if(getSettingValue_(r[0],null)===null)appendRow_('settings',{key:r[0],value:r[1],description:r[2],updated_at:now_()})}); if(!getAllRows_('academic_years').length)appendRow_('academic_years',{id:'AY0001',year_name:'2025/2026',semester:'Ganjil',start_date:'2025-07-01',end_date:'2025-12-31',status:'active',created_at:now_(),updated_at:now_()});}
function setupDefaultUsers_(){const u=getAllRows_('users'); if(!u.some(x=>x.username==='superadmin'))createDefaultUser_('USR0001','Super Administrator','superadmin','admin123','super_admin'); if(!u.some(x=>x.username==='admin'))createDefaultUser_('USR0002','Admin Prakerin','admin','admin123','admin');}
function createDefaultUser_(id,name,username,password,role){const salt=createSalt_(); appendRow_('users',{id,name,username,email:'',password_hash:hashPassword_(password,salt),salt,role,related_id:'',phone:'',photo_url:'',status:'active',session_token:'',token_expire:'',last_login:'',created_at:now_(),updated_at:now_()});}

function getSpreadsheet_(){const id=PropertiesService.getScriptProperties().getProperty('SPREADSHEET_ID'); if(!id)throw new Error('SPREADSHEET_ID belum ditemukan. Jalankan setupDatabase().'); return SpreadsheetApp.openById(id);}
function getSheet_(n){const s=getSpreadsheet_().getSheetByName(n); if(!s)throw new Error('Sheet tidak ditemukan: '+n); return s;}
function headers_(n){const sh=getSheet_(n); return sh.getLastColumn()?sh.getRange(1,1,1,sh.getLastColumn()).getValues()[0].map(x=>String(x||'').trim()):[];}
function getAllRows_(n){const sh=getSheet_(n),lr=sh.getLastRow(),lc=sh.getLastColumn(); if(lr<=1||!lc)return[]; const v=sh.getRange(1,1,lr,lc).getValues(),h=v[0].map(x=>String(x||'').trim()); return v.slice(1).filter(r=>r.some(c=>String(c||'')!=='')).map(r=>{const o={}; h.forEach((k,i)=>o[k]=r[i]); return o;});}
function appendRow_(n,o){const h=headers_(n); getSheet_(n).appendRow(h.map(k=>o[k]!==undefined?o[k]:'')); return o;}
function findRowById_(n,id){if(!id)return null; const sh=getSheet_(n),v=sh.getDataRange().getValues(); if(v.length<2)return null; const h=v[0].map(String),ix=h.indexOf('id'); for(let i=1;i<v.length;i++)if(String(v[i][ix])===String(id)){const o={}; h.forEach((k,j)=>o[k]=v[i][j]); return{rowIndex:i+1,data:o};} return null;}
function updateRowById_(n,id,o){const f=findRowById_(n,id); if(!f)throw new Error('Data tidak ditemukan: '+id); const sh=getSheet_(n),h=headers_(n); Object.keys(o).forEach(k=>{const i=h.indexOf(k); if(i>=0)sh.getRange(f.rowIndex,i+1).setValue(o[k]);}); return true;}
function deleteRowsAfterHeader_(n){const sh=getSheet_(n); if(sh.getLastRow()>1)sh.getRange(2,1,sh.getLastRow()-1,sh.getLastColumn()).clearContent();}
function generateId_(n,p){p=p||PREFIX[n]||'ID'; let m=0; getAllRows_(n).forEach(r=>{const x=Number(String(r.id||'').replace(p,'')); if(!isNaN(x)&&x>m)m=x;}); return p+String(m+1).padStart(4,'0');}
function now_(){return Utilities.formatDate(new Date(),APP_CONFIG.TIMEZONE,'yyyy-MM-dd HH:mm:ss');}
function today_(){return Utilities.formatDate(new Date(),APP_CONFIG.TIMEZONE,'yyyy-MM-dd');}
function nowTime_(){return Utilities.formatDate(new Date(),APP_CONFIG.TIMEZONE,'HH:mm:ss');}
function addMinutesToNow_(m){const d=new Date(); d.setMinutes(d.getMinutes()+Number(m||0)); return Utilities.formatDate(d,APP_CONFIG.TIMEZONE,'yyyy-MM-dd HH:mm:ss');}
function isExpired_(t){return t?new Date(String(t).replace(' ','T'))<new Date():false;}
function getSettingValue_(k,f){const r=getAllRows_('settings').find(x=>String(x.key)===String(k)); return r?r.value:(f===undefined?'':f);}
function updateSetting_(k,v){const r=getAllRows_('settings').find(x=>String(x.key)===String(k)); if(r){const sh=getSheet_('settings'),data=sh.getDataRange().getValues(),h=data[0],ki=h.indexOf('key'),vi=h.indexOf('value'),ui=h.indexOf('updated_at'); for(let i=1;i<data.length;i++)if(String(data[i][ki])===String(k)){sh.getRange(i+1,vi+1).setValue(v); if(ui>=0)sh.getRange(i+1,ui+1).setValue(now_()); return true;}} appendRow_('settings',{key:k,value:v,description:'',updated_at:now_()}); return true;}
function getSettingsObject_(){const o={}; getAllRows_('settings').forEach(r=>{let v=r.value; if(String(v).toLowerCase()==='true')v=true; if(String(v).toLowerCase()==='false')v=false; o[r.key]=v;}); return o;}
function paginateRows_(rows,d,fields){d=d||{}; let a=rows||[],q=String(d.search||'').toLowerCase().trim(); if(q)a=a.filter(r=>(fields||Object.keys(r)).some(f=>String(r[f]||'').toLowerCase().indexOf(q)>=0)); if(d.status)a=a.filter(r=>String(r.status||'')===String(d.status)); const page=Math.max(1,Number(d.page||1)),limit=Math.max(1,Number(d.limit||getSettingValue_('items_per_page',10))); return{items:a.slice((page-1)*limit,page*limit),pagination:{page,limit,total:a.length,total_pages:Math.ceil(a.length/limit)}};}
function logActivity_(p){try{return appendRow_('activity_logs',{id:generateId_('activity_logs'),user_id:p.user_id||'',role:p.role||'',action:p.action||'',module:p.module||'',description:p.description||'',ip_address:'',user_agent:'',created_at:now_()});}catch(e){return null;}}
function createSalt_(){return Utilities.getUuid().replace(/-/g,'');}
function hashPassword_(p,s){return Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256,String(p||'')+String(s||''),Utilities.Charset.UTF_8).map(b=>{const v=(b<0?b+256:b).toString(16); return v.length===1?'0'+v:v;}).join('');}
function createSessionToken_(){return Utilities.getUuid()+'-'+Utilities.getUuid();}
function sanitizeUser_(u){if(!u)return null; const x=Object.assign({},u); delete x.password_hash; delete x.salt; delete x.session_token; x.role_label=getRoleLabel_(x.role); return x;}
function normalizePhone_(p){let v=String(p||'').replace(/\s+|\-|\+/g,''); if(v.indexOf('0')===0)v='62'+v.slice(1); return v;}
function esc_(v){return String(v||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;');}
function val_(o,p,f){try{return String(p).split('.').reduce((a,k)=>a&&a[k],o)||f;}catch(e){return f;}}

function handleLogin_(d){const u=String(d.username||'').trim(),p=String(d.password||'').trim(); if(!u||!p)throw new Error('Username dan password wajib diisi.'); const user=getAllRows_('users').find(x=>String(x.username).toLowerCase()===u.toLowerCase()&&String(x.status||'active')==='active'); if(!user||hashPassword_(p,user.salt)!==String(user.password_hash))throw new Error('Username atau password salah.'); const token=createSessionToken_(), exp=addHours_(APP_CONFIG.SESSION_HOURS); updateRowById_('users',user.id,{session_token:token,token_expire:exp,last_login:now_(),updated_at:now_()}); const fresh=findRowById_('users',user.id).data; return{token,token_expire:exp,user:sanitizeUser_(fresh),menu_access:getRoleMenuAccess_(fresh.role),dashboard_route:'dashboard'};}
