function listGeneric_(d,sheet){requireAuth_(d.token); let rows=filterByRole_(sheet,getAllRows_(sheet),requireAuth_(d.token).user); Object.keys(d).forEach(k=>{if(k.endsWith('_id')||k==='status')rows= d[k]?rows.filter(r=>String(r[k])===String(d[k])):rows;}); const out=paginateRows_(rows,d,Object.keys(DB_SHEETS[sheet]||{})); out.items=out.items.map(r=>enrich_(sheet,r)); return out;}
function createGeneric_(d,cfg){admin_(d.token); cfg.create.forEach(k=>{if(!d[k])throw new Error(k+' wajib diisi.')}); if(cfg.unique&&d[cfg.unique]&&getAllRows_(cfg.sheet).some(x=>String(x[cfg.unique]).toLowerCase()===String(d[cfg.unique]).toLowerCase()))throw new Error('Data sudah ada: '+d[cfg.unique]); const row={}; DB_SHEETS[cfg.sheet].forEach(k=>row[k]=d[k]!==undefined?d[k]:''); row.id=generateId_(cfg.sheet); row.status=row.status||'active'; row.created_at=now_(); row.updated_at=now_(); appendRow_(cfg.sheet,row); return enrich_(cfg.sheet,row);}
function updateGeneric_(d,cfg){admin_(d.token); const f=findRowById_(cfg.sheet,d.id); if(!f)throw new Error('Data tidak ditemukan.'); updateRowById_(cfg.sheet,d.id,pick_(d,DB_SHEETS[cfg.sheet],f.data)); return enrich_(cfg.sheet,findRowById_(cfg.sheet,d.id).data);}
function deleteGeneric_(d,sheet){admin_(d.token); updateRowById_(sheet,d.id,{status:'inactive',updated_at:now_()}); return{id:d.id,status:'inactive'};}
function softStatus_(d,sheet,status){requireAuth_(d.token); updateRowById_(sheet,d.id,{status:status,updated_at:now_()}); return{id:d.id,status};}
function pick_(src,fields,old){const o={}; fields.forEach(k=>{if(k!=='id'&&k!=='created_at'&&src[k]!==undefined&&src[k]!==null&&String(src[k])!=='')o[k]=src[k]; else if(old&&old[k]!==undefined)o[k]=old[k];}); o.updated_at=now_(); return o;}
function enrich_(sheet,r){const e=Object.assign({},r); if(r.period_id)e.period=row_('periods',r.period_id); if(r.student_id)e.student=row_('students',r.student_id); if(r.teacher_id)e.teacher=row_('teachers',r.teacher_id); if(r.industry_id)e.industry=row_('industries',r.industry_id); if(r.major_id)e.major=row_('majors',r.major_id); if(r.class_id)e.class=row_('classes',r.class_id); if(r.homeroom_teacher_id)e.homeroom_teacher=row_('teachers',r.homeroom_teacher_id); if(r.industry_mentor_id)e.industry_mentor=row_('industry_mentors',r.industry_mentor_id); if(e.student){e.class=row_('classes',e.student.class_id); e.major=row_('majors',e.student.major_id);} if(sheet==='industries')e.mentors=getAllRows_('industry_mentors').filter(x=>String(x.industry_id)===String(r.id)); if(sheet==='attendance')e.status_label=getAttendanceStatusLabel_(r.status); return e;}
function row_(s,id){return ((findRowById_(s,id)||{}).data)||null;}

