function handleScanQrAttendance_(d){const a=requireAuth_(d.token); if(a.user.role!=='siswa')throw new Error('Presensi QR hanya untuk siswa.'); const p=String(d.qr_text||d.qr||'').split('|'); if(p.length!==3||p[0]!=='SIPRAK')throw new Error('Format QR tidak valid.'); const s=row_('qr_sessions',p[1]); if(!s||s.qr_token!==p[2])throw new Error('Token QR tidak valid.'); if(s.status!=='active'||isExpired_(s.expired_at))throw new Error('QR tidak aktif atau kedaluwarsa.'); const plc=getAllRows_('placements').find(x=>String(x.student_id)===String(a.user.related_id)&&String(x.period_id)===String(s.period_id)&&String(x.status)==='active'); if(!plc)throw new Error('Siswa belum memiliki penempatan aktif.'); if(String(plc.industry_id)!==String(s.industry_id))throw new Error('QR tidak sesuai dengan DU/DI siswa.'); if(getAllRows_('attendance').some(x=>String(x.session_id)===String(s.id)&&String(x.student_id)===String(a.user.related_id)))throw new Error('Anda sudah presensi.'); const row={id:generateId_('attendance'),session_id:s.id,period_id:s.period_id,placement_id:plc.id,student_id:a.user.related_id,industry_id:plc.industry_id,teacher_id:plc.teacher_id,date:s.session_date,status:'H',check_in:nowTime_(),check_out:'',method:'qr',location:d.location||'',photo_url:d.photo_url||'',validation_status:'valid',validated_by:'system',validated_at:now_(),notes:'Presensi QR',created_at:now_(),updated_at:now_()}; appendRow_('attendance',row); appendRow_('attendance_logs',{id:generateId_('attendance_logs'),session_id:s.id,student_id:a.user.related_id,placement_id:plc.id,scan_time:now_(),scan_result:'success',message:'Presensi berhasil',device_info:d.device_info||'',ip_address:'',created_at:now_()}); createAttendanceNotifications_(row); return enrich_('attendance',row);}
