function calcScore_(d){const f=['discipline_score','responsibility_score','skill_score','communication_score','initiative_score','safety_score','industry_score','teacher_score','journal_score','attendance_score','final_report_score']; const o={}; f.forEach(k=>o[k]=Math.max(0,Math.min(100,Number(d[k]||0)))); if(!o.industry_score)o.industry_score=avg_([o.discipline_score,o.responsibility_score,o.skill_score,o.communication_score,o.initiative_score,o.safety_score]); if(!o.teacher_score)o.teacher_score=avg_([o.discipline_score,o.responsibility_score,o.communication_score,o.initiative_score]); const final_score=Math.round(o.industry_score*.5+o.teacher_score*.25+avg_([o.journal_score,o.final_report_score])*.15+o.attendance_score*.1); return Object.assign(o,{final_score,predicate:final_score>=90?'Sangat Baik':final_score>=80?'Baik':final_score>=70?'Cukup':'Perlu Pembinaan',competency_status:final_score>=70?'kompeten':'belum_kompeten'});}
