function dashboard_(u){const placements=filterByRole_('placements',getAllRows_('placements'),u),attendance=filterByRole_('attendance',getAllRows_('attendance'),u),journals=filterByRole_('journals',getAllRows_('journals'),u),monitoring=filterByRole_('monitoring',getAllRows_('monitoring'),u),assessments=filterByRole_('assessments',getAllRows_('assessments'),u),certificates=filterByRole_('certificates',getAllRows_('certificates'),u); const as=summarizeAttendance_(attendance), js=summarizeJournals_(journals), ms=summarizeMonitoring_(monitoring), ps=summarizePlacements_(placements), ns=summarizeAssessments_(assessments); return{generated_at:now_(),role:u.role,role_label:getRoleLabel_(u.role),active_period:getActivePeriod_(),cards:{students:getAllRows_('students').length,industries:getAllRows_('industries').length,placements:placements.length,attendance:attendance.length,journals:journals.length,monitoring:monitoring.length,assessments:assessments.length,certificates:certificates.length},placement_summary:ps,attendance_summary:as,journal_summary:js,monitoring_summary:ms,assessment_summary:ns,charts:{attendance_chart:[{label:'Hadir',value:as.H},{label:'Izin',value:as.I},{label:'Sakit',value:as.S},{label:'Alfa',value:as.A}],journal_chart:[{label:'Dikirim',value:js.submitted},{label:'Final',value:js.final}],assessment_chart:[{label:'Sangat Baik',value:ns.sangat_baik},{label:'Baik',value:ns.baik},{label:'Cukup',value:ns.cukup}]},recent:{placements:placements.slice(-5).map(x=>enrich_('placements',x)),attendance:attendance.slice(-5).map(x=>enrich_('attendance',x)),journals:journals.slice(-5).map(x=>enrich_('journals',x)),monitoring:monitoring.slice(-5).map(x=>enrich_('monitoring',x)),assessments:assessments.slice(-5).map(x=>enrich_('assessments',x))}};}
