function summarizeAttendance_(r){const o={total:r.length,H:0,I:0,S:0,A:0,valid:0,pending:0,rejected:0,attendance_percentage:0}; r.forEach(x=>{const s=String(x.status||'').toUpperCase(); if(o[s]!==undefined)o[s]++; if(o[x.validation_status]!==undefined)o[x.validation_status]++;}); o.attendance_percentage=o.total?Math.round(o.H/o.total*100):0; return o;}
function summarizeJournals_(r){const o={total:r.length,submitted:0,teacher_approved:0,industry_approved:0,revision:0,rejected:0,final:0,cancelled:0}; r.forEach(x=>{if(o[x.status]!==undefined)o[x.status]++}); return o;}
