function summarizeAssessments_(r){const o={total:r.length,total_assessments:r.length,published:0,draft:0,kompeten:0,belum_kompeten:0,average_score:0,sangat_baik:0,baik:0,cukup:0,perlu_pembinaan:0,by_predicate:[]}; let t=0; r.forEach(x=>{t+=Number(x.final_score||0); if(x.published_status==='published')o.published++; else o.draft++; if(x.competency_status==='kompeten')o.kompeten++; if(x.competency_status==='belum_kompeten')o.belum_kompeten++; if(x.predicate==='Sangat Baik')o.sangat_baik++; if(x.predicate==='Baik')o.baik++; if(x.predicate==='Cukup')o.cukup++; if(x.predicate==='Perlu Pembinaan')o.perlu_pembinaan++;}); o.average_score=r.length?Math.round(t/r.length):0; return o;}


