function handleGetUploadConfig_(data){requireUploadAccess_(String(data.token||'')); return{upload_store:'google_drive',metadata_sheet:'media_files',store_metadata_only:true,allowed_mime:'all',allowed_extension:'all',supported_image_extensions:['jpg','jpeg','png','webp','gif','svg','ico','bmp','avif','heic','heif'],supported_favicon_extensions:['ico','png','jpg','jpeg','svg','webp','gif','bmp','avif'],note:'File disimpan di Google Drive, Spreadsheet hanya metadata/URL. Gambar dan favicon dapat memakai semua format gambar yang didukung browser.'};}
function handleUploadFile_(data){const auth=requireUploadAccess_(String(data.token||'')); const fileName=String(data.file_name||'').trim(), mimeType=String(data.mime_type||'application/octet-stream').trim(), base64Data=String(data.base64_data||'').trim(), moduleName=String(data.module||'general').trim(), relatedId=String(data.related_id||'').trim(), description=String(data.description||'').trim(); if(!fileName)throw new Error('Nama file wajib diisi.'); if(!base64Data)throw new Error('Data file wajib diisi.'); const bytes=Utilities.base64Decode(cleanBase64FileData_(base64Data)); const root=getOrCreateUploadRootFolder_(); const folder=getOrCreateChildFolder_(root,sanitizeFileName_(moduleName)); const safeName=buildSafeUploadFileName_(fileName); const blob=Utilities.newBlob(bytes,mimeType,safeName); const file=folder.createFile(blob); if(String(getSettingValue_('upload_public_access','true'))==='true')file.setSharing(DriveApp.Access.ANYONE_WITH_LINK,DriveApp.Permission.VIEW); const fileId=file.getId(); const row={id:generateId_('media_files'),file_id:fileId,file_name:safeName,original_name:fileName,mime_type:mimeType,file_size:bytes.length,file_extension:getFileExtension_(fileName),file_url:file.getUrl(),download_url:'https://drive.google.com/uc?export=download&id='+fileId,thumbnail_url:buildDriveThumbnailUrl_(fileId,mimeType),folder_id:folder.getId(),module:moduleName,related_id:relatedId,description:description,uploaded_by:auth.user.id,status:'active',created_at:now_(),updated_at:now_()}; appendRow_('media_files',row); logActivitySafe_({user_id:auth.user.id,role:auth.user.role,action:'UPLOAD',module:'media_files',description:'Upload file: '+safeName}); return row;}
function handleListMediaFiles_(data){const auth=requireUploadAccess_(String(data.token||'')); let rows=getAllRows_('media_files').filter(r=>String(r.status||'active')==='active'); const role=String(auth.user.role||''); if(['super_admin','admin','humas','kurikulum','kepala_sekolah'].indexOf(role)===-1){rows=rows.filter(r=>String(r.uploaded_by)===String(auth.user.id)||String(r.related_id)===String(auth.user.related_id||''));} if(data.module)rows=rows.filter(r=>String(r.module)===String(data.module)); if(data.related_id)rows=rows.filter(r=>String(r.related_id)===String(data.related_id)); if(data.mime_group==='image')rows=rows.filter(r=>String(r.mime_type||'').indexOf('image/')===0); if(data.mime_group==='document')rows=rows.filter(r=>String(r.mime_type||'').indexOf('image/')!==0); rows.sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||''))); return paginateRows_(rows,data,['file_name','original_name','mime_type','module','related_id','description','status']);}
function handleDeleteMediaFile_(data){const auth=requireUploadAccess_(String(data.token||'')); const id=String(data.id||'').trim(); if(!id)throw new Error('ID file wajib diisi.'); const f=findRowById_('media_files',id); if(!f)throw new Error('File tidak ditemukan.'); const can=['super_admin','admin','humas','kurikulum'].indexOf(String(auth.user.role))!==-1||String(f.data.uploaded_by)===String(auth.user.id); if(!can)throw new Error('Anda tidak berhak menghapus file ini.'); updateRowById_('media_files',id,{status:'inactive',updated_at:now_()}); logActivitySafe_({user_id:auth.user.id,role:auth.user.role,action:'DELETE',module:'media_files',description:'Nonaktifkan file: '+id}); return{id:id,status:'inactive'};}
function getOrCreateUploadRootFolder_(){const configured=String(getSettingValue_('drive_upload_root_folder_id','')||'').trim(); if(configured){try{return DriveApp.getFolderById(configured)}catch(e){updateSetting_('drive_upload_root_folder_id','')}} const name='UPLOAD-'+APP_CONFIG.APP_NAME; const folders=DriveApp.getFoldersByName(name); const folder=folders.hasNext()?folders.next():DriveApp.createFolder(name); updateSetting_('drive_upload_root_folder_id',folder.getId()); return folder;}
function getOrCreateChildFolder_(parent,name){const safe=name||'general'; const folders=parent.getFoldersByName(safe); return folders.hasNext()?folders.next():parent.createFolder(safe);}
function cleanBase64FileData_(v){let t=String(v||'').trim(); if(t.indexOf('base64,')!==-1)t=t.split('base64,')[1]; return t;}
function sanitizeFileName_(name){return String(name||'file').replace(/[\\\/:*?"<>|#%{}$!'@+`=]/g,'-').replace(/\s+/g,'-').replace(/-+/g,'-').substring(0,120);}
function buildSafeUploadFileName_(original){const ext=getFileExtension_(original); const base=String(original||'file').replace(/\.[^/.]+$/,''); const stamp=Utilities.formatDate(new Date(),APP_CONFIG.TIMEZONE,'yyyyMMdd-HHmmss'); const safe=sanitizeFileName_(base); return ext?safe+'-'+stamp+'.'+ext:safe+'-'+stamp;}
function getFileExtension_(name){const t=String(name||''); return t.indexOf('.')===-1?'':t.split('.').pop().toLowerCase();}
function buildDriveThumbnailUrl_(id,mime){return String(mime||'').indexOf('image/')===0?'https://drive.google.com/thumbnail?id='+id+'&sz=w600':'';}
function logActivitySafe_(payload){try{appendRow_('activity_logs',{id:generateId_('activity_logs'),user_id:payload.user_id||'',role:payload.role||'',action:payload.action||'',module:payload.module||'',description:payload.description||'',ip_address:'',user_agent:'',created_at:now_()});}catch(e){Logger.log(e.message)}}

