function normalizeRole_(role){
  role=String(role||'').trim().toLowerCase();
  const alias={
    industri:'pembimbing_dudi',
    pembimbing_industri:'pembimbing_dudi',
    pembimbing_du_di:'pembimbing_dudi',
    pembimbing_dunia_usaha:'pembimbing_dudi',
    dunia_usaha:'pembimbing_dudi',
    orangtua:'orang_tua',
    wali_murid:'orang_tua',
    wali_siswa:'orang_tua',
    parent:'orang_tua'
  };
  return alias[role]||role;
}
function isActiveStatus_(status){
  const v=String(status||'active').trim().toLowerCase();
  return ['active','aktif','1','true','yes','ya'].indexOf(v)>=0;
}
function verifyPasswordFlexible_(user,password){
  if(!user)return false;
  const pass=String(password||'');
  const salt=String(user.salt||'').trim();
  const storedHash=String(user.password_hash||'').trim();
  if(salt && storedHash && hashPassword_(pass,salt)===storedHash)return true;
  if(storedHash && hashPassword_(pass,'')===storedHash)return true;
  const legacyPlain=String(user.password||user.plain_password||user.password_plain||'').trim();
  if(legacyPlain && legacyPlain===pass)return true;
  if(storedHash && storedHash===pass)return true;
  return false;
}
function migratePasswordIfNeeded_(user,password){
  if(!user||!user.id)return false;
  const salt=String(user.salt||'').trim();
  const storedHash=String(user.password_hash||'').trim();
  if(salt && storedHash && hashPassword_(password,salt)===storedHash)return false;
  if(verifyPasswordFlexible_(user,password)){
    const ns=createSalt_();
    updateRowById_('users',user.id,{password_hash:hashPassword_(password,ns),salt:ns,updated_at:now_()});
    return true;
  }
  return false;
}
function sanitizeUser_(u){
  if(!u)return null;
  const x=Object.assign({},u);
  x.role=normalizeRole_(x.role);
  delete x.password;
  delete x.plain_password;
  delete x.password_plain;
  delete x.password_hash;
  delete x.salt;
  delete x.session_token;
  x.role_label=getRoleLabel_(x.role);
  return x;
}
function requireRole_(t,roles){
  const a=requireAuth_(t);
  const userRole=normalizeRole_(a.user.role);
  const allowed=(roles||[]).map(normalizeRole_);
  if(allowed.indexOf(userRole)<0)throw new Error('Akses ditolak untuk role: '+getRoleLabel_(userRole));
  return a;
}
function handleLogin_(d){
  const u=String(d.username||'').trim();
  const p=String(d.password||'');
  if(!u||!p)throw new Error('Username dan password wajib diisi.');
  const user=getAllRows_('users').find(x=>String(x.username||'').trim().toLowerCase()===u.toLowerCase()&&isActiveStatus_(x.status));
  if(!user||!verifyPasswordFlexible_(user,p))throw new Error('Username atau password salah.');
  migratePasswordIfNeeded_(user,p);
  const freshBefore=findRowById_('users',user.id).data;
  const token=createSessionToken_(), exp=addHours_(APP_CONFIG.SESSION_HOURS);
  updateRowById_('users',freshBefore.id,{role:normalizeRole_(freshBefore.role),session_token:token,token_expire:exp,last_login:now_(),updated_at:now_()});
  const fresh=findRowById_('users',freshBefore.id).data;
  return{token,token_expire:exp,user:sanitizeUser_(fresh),menu_access:getRoleMenuAccess_(fresh.role),dashboard_route:'dashboard'};
}
