  if(!f)throw new Error('User tidak ditemukan.');
  const up=pick_(d,['name','username','email','role','related_id','phone','photo_url','status'],f.data);
  if(up.username && getAllRows_('users').some(x=>String(x.id)!==String(d.id)&&String(x.username||'').trim().toLowerCase()===String(up.username).trim().toLowerCase()))throw new Error('Username sudah digunakan oleh user lain.');
  if(up.role)up.role=normalizeRole_(up.role);
  if(String(d.password||'').trim()){
    const salt=createSalt_();
    up.password_hash=hashPassword_(String(d.password),salt);
    up.salt=salt;
    up.session_token='';
    up.token_expire='';
  }
  updateRowById_('users',d.id,up);
  return sanitizeUser_(findRowById_('users',d.id).data);
}
