  if(d.end_date)a=a.filter(r=>String(r.date||r.journal_date||r.monitoring_date||r.issue_date||r.end_date||r.created_at||'')<=String(d.end_date));
  return a;
}
function handleUploadFile_(data){
  const auth=requireUploadAccess_(String(data.token||''));
  const fileName=String(data.file_name||'').trim(), mimeType=String(data.mime_type||'application/octet-stream').trim(), base64Data=String(data.base64_data||'').trim(), moduleName=String(data.module||'general').trim();
  let relatedId=String(data.related_id||'').trim();
  const description=String(data.description||'').trim();
  if(!fileName)throw new Error('Nama file wajib diisi.');
  if(!base64Data)throw new Error('Data file wajib diisi.');
  if(!relatedId){
    relatedId='REL-'+sanitizeFileName_(moduleName).toUpperCase()+'-'+Utilities.formatDate(new Date(),APP_CONFIG.TIMEZONE,'yyyyMMddHHmmss')+'-'+Utilities.getUuid().slice(0,6).toUpperCase();
  }
  const bytes=Utilities.base64Decode(cleanBase64FileData_(base64Data));
  const root=getOrCreateUploadRootFolder_();
  const folder=getOrCreateChildFolder_(root,sanitizeFileName_(moduleName));
  const safeName=buildSafeUploadFileName_(fileName);
  const blob=Utilities.newBlob(bytes,mimeType,safeName);
  const file=folder.createFile(blob);
  if(String(getSettingValue_('upload_public_access','true'))==='true')file.setSharing(DriveApp.Access.ANYONE_WITH_LINK,DriveApp.Permission.VIEW);
  const fileId=file.getId();
  const row={id:generateId_('media_files'),file_id:fileId,file_name:safeName,original_name:fileName,mime_type:mimeType,file_size:bytes.length,file_extension:getFileExtension_(fileName),file_url:file.getUrl(),download_url:'https://drive.google.com/uc?export=download&id='+fileId,thumbnail_url:buildDriveThumbnailUrl_(fileId,mimeType),folder_id:folder.getId(),module:moduleName,related_id:relatedId,description:description,uploaded_by:auth.user.id,status:'active',created_at:now_(),updated_at:now_()};
  appendRow_('media_files',row);
  logActivitySafe_({user_id:auth.user.id,role:auth.user.role,action:'UPLOAD',module:'media_files',description:'Upload file: '+safeName});
  return row;
}
